int plat_store_load(uint32_t obj, void *dst, uint32_t max)
{
    int n;
    store_ready();
    if (obj >= OBJ_NOBJ || (n = store_len[obj]) < 0)
        return -1;
    if ((uint32_t)n > max)
        n = (int)max;
    memcpy(dst, store[obj], (size_t)n);
    return n;
}

/* one SysEx message (F0 .. F7) out over USB: 0 sent, -2 busy (again later), -1 nobody there */
static int bs_send(const uint8_t *m, unsigned n)
{
    return plat_sysex_try(m, n);
}

/* the mask blurred (three box passes, about a Gaussian of the radius) and added as light; the mask is used up */
static void mask_glow(float radius, rgb_t c, float k)
{
    int r = (int)(radius * 0.9f + 0.5f), pass, x, y;
    static uint16_t line[SW];
    if (r < 1)
        r = 1;
    for (pass = 0; pass < 3; pass++) {
        for (y = mbox.y0; y < mbox.y1; y++) {         /* rows */
            int acc = 0, w = 2 * r + 1;
            uint8_t *m = MASK + y * SW;
            for (x = mbox.x0; x < mbox.x1; x++)
                line[x] = m[x];
            for (x = mbox.x0 - r; x < mbox.x1; x++) {
                int xa = x + r, xb = x - r - 1;
                if (xa < mbox.x1)
                    acc += line[xa];
                if (xb >= mbox.x0)
                    acc -= line[xb];
                if (x >= mbox.x0)
                    m[x] = (uint8_t)(acc / w);
            }
        }
        for (x = mbox.x0; x < mbox.x1; x++) {         /* columns */
            int acc = 0, w = 2 * r + 1;
            for (y = mbox.y0; y < mbox.y1; y++)
                line[y] = MASK[y * SW + x];
            for (y = mbox.y0 - r; y < mbox.y1; y++) {
                int ya = y + r, yb = y - r - 1;
                if (ya < mbox.y1)
                    acc += line[ya];
                if (yb >= mbox.y0)
                    acc -= line[yb];
                if (y >= mbox.y0)
                    MASK[y * SW + x] = (uint8_t)(acc / w);
            }
        }
    }
    mask_addlight(c, k);
}

static void boot_step(int f)
{
    float t = (float)f / (BOOT_FRAMES - 1), pres, lid, gl, title, by, u;
    pres = 0.25f + t / 0.12f;
    pres = pres > 1 ? 1 : pres;
    u = (t - 0.12f) / 0.42f;
    u = u < 0 ? 0 : u > 1 ? 1 : u;
    lid = 42 * (0.5f - 0.5f * fcos_(PI_F * u));
    gl = (t >= 0.52f && t <= 0.84f) ? (t - 0.52f) / 0.32f : -1;
    title = (t - 0.62f) / 0.2f;
    title = title < 0 ? 0 : title > 1 ? 1 : title;
    by = (t - 0.8f) / 0.15f;
    by = by < 0 ? 0 : by > 1 ? 1 : by;
    boot_frame(lid, pres, gl, title, by);
}

static void draw_page(void)
{
    int force = ui.full || ui.drawn_page != ui.page;
    if (force) {
        art_load(ui.page == PG_PLAY ? &ART_PLAY : &ART_SET);
        restore(0, SH);
        ui.drawn_page = ui.page;
        ui.head_q = ui.strip_q = -1;
        ui.full = 0;
        if (ui.page == PG_TONE)
            tone_page(set.curve, au.last_vel ? (int)au.last_vel : 88);
        else if (ui.page == PG_ROOM)
            room_page(set.room, set.size / 100.0f, set.amount / 100.0f, set.width / 100.0f);
        else if (ui.page == PG_LAYER)
            layer_page();
        else if (ui.page == PG_SETUP)
            setup_page();
        else if (ui.page == PG_ABOUT)
            about_page();
    }
    if (ui.head_q < 0 || (ui.msg_until && plat_ms() >= ui.msg_until) ||
        (ui.debug && plat_ms() - ui.debug_drawn > 500u)) {
        if (ui.msg_until && plat_ms() >= ui.msg_until)
            ui.msg_until = 0;
        ui.debug_drawn = plat_ms();
        ui.head_q = 0;
        draw_header();
    }
    if (ui.strip_q < 0 || (ui.page == PG_ABOUT && plat_ms() - ui.debug_drawn > 500u)) {
        ui.strip_q = 0;
        ui.debug_drawn = plat_ms();
        draw_strip();
    }
    if (ui.page == PG_PLAY)
        draw_play(force);
    else if (ui.page == PG_TONE && (int)au.last_vel != ui.vel_q) {
        ui.vel_q = (int)au.last_vel;
        ui.full = 1;                          /* the dot follows the last note: next frame */
    } else if (ui.page == PG_SETUP) {
        uint32_t q = setup_live();
        if (q != ui.setup_q) {                /* the pedals, the jack, the pads changed: next frame */
            ui.setup_q = q;
            ui.full = 1;
        }
    }
    flush();
}

static int usb_str_desc(const char *s, const uint8_t **d, uint16_t *l)
{
    uint32_t n = 0;
    while (s[n] && n < 31u) {
        usb_str_buf[2 + 2 * n] = (uint8_t)s[n];
        usb_str_buf[3 + 2 * n] = 0;
        n++;
    }
    usb_str_buf[0] = (uint8_t)(2 + 2 * n);
    usb_str_buf[1] = 3;
    *d = usb_str_buf;
    *l = (uint16_t)(2 + 2 * n);
    return 1;
}

static void usb_start(void)                             /* boot, or main-loop retry while usb.up == 0 */
{
    usb.timeouts = 0;
    fm1_usb_reset();                                    /* reset whatever the ROM left */
    fm1_delay_ms(25);
    fm1_usb_attach(ep0buf);
    sie_wr(S_POWER, 0x60);
    sie_wr(S_INTRUSBE, 0x07);                           /* suspend, resume, reset (polled) */
    sie_wr(S_INTRTX1E, 0x01);
    sie_wr(S_INTRTX2E, 0);
    sie_wr(S_INTRRX1E, 0);
    sie_wr(S_INTRRX2E, 0);
    fm1_usb_ep_enable(0x1Fu);
    usb.up = usb.timeouts < 3u;                         /* a dead SIE leaves USB off */
}

/* returns only when nothing was committed (refused, failed, or dry run) */
static int ota_session(void)
{
    static uint8_t parm[112];
    uint8_t back[112];
    uint32_t i;
    int rc;
    ota_deadline = ota_now_ms() + 120000u;          /* step 1 normally takes ~5 s; a stalled host gives up after 2 min */
    rc = ota_stage();
    if (rc) {
        ota_unstage();
        ota_show(9, rc);
        return rc;
    }
    /* 5./7. UPDATA_PARM (update_mode_api_v2 layout), flash copy first */
    for (i = 0; i < sizeof parm; i++)
        parm[i] = 0;
    ota_wr16(parm + 2, 0x5A0Du);
    ota_wr16(parm + 4, 0x5A01u);
    ota_wr16(parm + 6, 0x5441u);
#if defined(BOARD_SMK37) && BOARD_SMK37
    for (i = 0; i < sizeof OTA_PARM_ID - 1u; i++)    /* zero after it, up to +0x27 */
        parm[8 + i] = (uint8_t)OTA_PARM_ID[i];       /* the loader's own USB identity */
#else
    for (i = 0; i < 12u; i++)
        parm[8 + i] = (uint8_t)"ota-FM-1_015"[i];    /* the loader's own USB identity */
#endif
    ota_wr32(parm + 72, OTA_AREA);
    ota_wr16(parm, ota_crc16(parm + 2, 78, 0));
#if FELUCCA_OTA_DRYRUN
    ota_unstage();
    ota_show(9, 1);                                 /* 1 = dry run complete */
    return 1;
#endif
#ifndef FELUCCA_OTA_RAMONLY
#define FELUCCA_OTA_RAMONLY 0                       /* 1: RAM record only, no power-loss resume (a power
                                                     * cycle leaves a broken loader behind) */
#endif
    if (!FELUCCA_OTA_RAMONLY && (ota_prog(OTA_RES, parm, sizeof parm) || ota_fread(OTA_RES, back, sizeof back) ||
        !ota_memeq(back, parm, sizeof parm))) {
        ota_unstage();
        ota_show(9, -14);
        return -14;
    }
    ota_show(5, 0);
    ota_commit(parm);
    return 0;
}

void erk_set_room(int type, int size_q15, int amount_q15)
{
    type = clampi(type, ERK_REV_OFF, ERK_REV_CHURCH);
    size_q15 = clampi(size_q15, 0, 32767);
    if (type != st.rev_type || size_q15 != st.rev_size) {
        st.rev_type = type;
        st.rev_size = size_q15;
        st.rev_dirty = 1;
    }
    st.rev_mix = clampi(amount_q15, 0, 32767);
}

void erk_click(int accent)
{
    clk_c = 0;
    clk_s = 1 << 14;
    clk_rc = accent ? 15657 : 15960;                  /* cos / sin (Q14) of 2 pi f / 44100 */
    clk_rs = accent ? 4830 : 3703;
    clk_amp = accent ? 9000 : 6000;
    clk_n = 1100;
}

int erk_pad_active(void)
{
    int i, n = 0;
    for (i = 0; i < ERK_PADV; i++)
        n += pv[i].state != P_FREE;
    return n;
}
